<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $wedding->name }} · Casa de Bodas</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Playfair+Display:wght@500;600&display=swap" rel="stylesheet"><style>*{box-sizing:border-box}body{margin:0;background:#fbf7f3;color:#392d2c;font:14px 'DM Sans',Arial}.nav{height:70px;display:flex;align-items:center;justify-content:space-between;padding:0 5vw;background:#fffdfae8}.brand{color:#814b55;text-decoration:none;font:600 17px 'Playfair Display',Georgia}.menu{border:0;border-radius:50%;width:45px;height:45px;background:#f7e8e5;color:#914f5d;font-size:21px}.workspace-menu{display:none;position:fixed;z-index:30;right:5vw;top:62px;width:min(88vw,300px);padding:14px;border:1px solid #ead8d0;border-radius:18px;background:#fffdfa;box-shadow:0 18px 42px #5d38252b}.workspace-menu.open{display:block}.workspace-menu a,.workspace-menu button{display:block;width:100%;padding:11px 4px;border:0;border-bottom:1px solid #f0e2db;background:none;color:#5f4946;text-align:left;text-decoration:none;font:13px 'DM Sans',Arial}.workspace-menu button{color:#934e5b}.next{max-width:900px;margin:0 auto;padding:0 5vw 60px}.next h2{margin:6px 0 13px;font:28px 'Playfair Display',Georgia}.eyebrow{font-size:10px;letter-spacing:.22em;color:#a35e68;font-weight:600}.event{display:flex;gap:14px;align-items:center;padding:12px;border:1px solid #ead8d0;border-radius:18px;background:#fffdfa}.event img{width:110px;height:82px;object-fit:cover;border-radius:12px}.event b,.event small{display:block}.event small{margin-top:5px;color:#77635e}</style></head><body><nav class="nav"><a class="brand" href="{{ $basePath }}/dashboard">♡ {{ $wedding->name }}</a><button class="menu" type="button" aria-label="Abrir menú" aria-expanded="false">☰</button></nav><aside class="workspace-menu" aria-label="Menú de la boda"><a href="{{ $basePath }}/dashboard">Panel principal</a><a href="{{ $basePath }}/bodas/{{ $wedding->id }}/centro">Centro de trabajo</a><form method="POST" action="{{ $basePath }}/logout">@csrf<button>Cerrar sesión</button></form></aside><x-wedding-areas-menu :navigation="$navigation" :base-path="$basePath" active-route="weddings.workspace" />@php($event=$wedding->events->first())<section class="next"><p class="eyebrow">EVENTO PRÓXIMO</p><h2>{{ $event?->name ?: 'Evento por definir' }}</h2><div class="event"><img src="{{ $basePath }}/images/casa-de-bodas-hero.png" alt="Decoración de boda"><div><b>{{ $event?->venue ?: 'Lugar pendiente' }}</b><small>{{ $event?->event_date?->translatedFormat('d \d\e F Y') ?: 'Fecha pendiente' }}</small><small>{{ $event?->event_time ?: 'Hora pendiente' }}</small></div></div></section><script>const b=document.querySelector('.menu'),m=document.querySelector('.workspace-menu');b?.addEventListener('click',()=>{m.classList.toggle('open');b.setAttribute('aria-expanded',m.classList.contains('open'))})</script></body></html>
